import{_ as t,c as n,j as e,a as r,o}from"./chunks/framework.CqbvlPrP.js";const u=JSON.parse('{"title":"第一百三十章 真正的出家人","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/130第一百三十章 真正的出家人.md","filePath":"meditation/巴利文大藏经/130第一百三十章 真正的出家人.md"}'),l={name:"meditation/巴利文大藏经/130第一百三十章 真正的出家人.md"};function _(s,a,i,d,p,c){return o(),n("div",null,a[0]||(a[0]=[e("h1",{id:"第一百三十章-真正的出家人",tabindex:"-1"},[r("第一百三十章 真正的出家人 "),e("a",{class:"header-anchor",href:"#第一百三十章-真正的出家人","aria-label":'Permalink to "第一百三十章 真正的出家人"'},"​")],-1),e("p",null,"完全读懂巴利文大藏经",-1),e("p",null,"相应部14相应37经/沙门婆罗门经(界相应/因缘篇/修多罗)",-1),e("p",null,"有个时候，佛陀住在舍卫城的祇树林给孤独园，有一天，佛陀对出家弟子们说：“弟子们，世间有四界，是哪四界呢？就是地界、水界、火界、风界（地界、水界、火界、风界解释，见第一百二十四章）。弟子们，任何的出家人、修行人如果他们不能证悟得知：地界、水界、火界、风界这四界的吸引力是什么？对四界渴爱、热爱的滋味是什么？四界的祸患是什么？如何才能从四界中解脱出来（四界吸引力、祸患、解脱解释，见第一百二十五章）？这些问题，弟子们，对于如来来说他们就不是真正的修行人、出家人，他们就不是被修行团体认可的修行人，他们就不是被僧团认可的出家人。他们不明白修行和出家的真正意义，他们无法证悟解脱的果位。",-1),e("p",null,"弟子们，任何的出家人、修行人如果他们证悟得知：地界、水界、火界、风界这四界的吸引力是什么？对四界渴爱、热爱的滋味是什么？四界的祸患是什么？如何才能从四界中解脱出来（四界吸引力、祸患、解脱解释，见第一百二十五章）？这些问题，弟子们，对于如来来说他们就是真正的修行人、出家人，他们就是被修行团体认可的修行人，他们就是被僧团认可的出家人。他们明白修行和出家的真正意义，他们能够最终证悟解脱的果位。”",-1),e("p",null,"佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。",-1)]))}const f=t(l,[["render",_]]);export{u as __pageData,f as default};
